case "ews": {
  const request = new XMLHttpRequest();
  request.open("GET", `https://${this.hostname}:${this.port}/`);
  request.onerror = () =>
    this.#handleSecurityInfo(
      request.channel.status,
      request.channel.securityInfo
    );
  request.onload = () =>
    this.#handleSecurityInfo(
      request.channel.status,
      request.channel.securityInfo
    );
  request.send(null);
  return;
}
